6|
7|const server = new McpServer({
8|  name: 'hermes-oh-my-pi-mcp',
9|  version: '0.1.0',
10|});
11|
12|server.tool(
13|  'prompt',
14|  'Run oh-my-pi (omp) in one-shot mode and return the result as text or JSON.',
15|  {
16|    prompt: z.string().min(1),
17|    cwd: z.string().optional(),
18|    model: z.string().optional(),
19|    provider: z.string().optional(),
20|    profile: z.string().optional(),
21|    noSession: z.boolean().optional(),
22|    mode: z.enum(['text', 'json']).optional(),
23|  },
24|  async (input) => {
25|    const ompBinary = resolveOmpBinary();
26|    const runner = resolveRunnerBinary();
27|    const cwd = normalizeCwd(input.cwd);
28|    const args = buildOmpArgs({
29|      prompt: input.prompt,
30|      cwd,
31|      model: input.model,
32|      provider: input.provider,
33|      profile: input.profile,
34|      noSession: input.noSession,
35|      mode: input.mode ?? 'json',
36|    });
37|
38|    const result = await runCommand(runner, [ompBinary, ...args], { cwd });
39|    if (result.code !== 0) {
40|      throw new Error(`omp exited with code ${result.code}: ${result.stderr.trim() || result.stdout.trim() || 'no output'}`);
41|    }
42|
43|    const raw = (result.stdout || '').trim();
44|    const parsed = safeParseJson(raw);
45|    const text = parsed ? JSON.stringify(parsed, null, 2) : raw || '(empty response)';
46|
47|    return {
48|      content: [
49|        { type: 'text', text },
50|      ],
51|    };
52|  }
53|);
54|
55|server.tool(
56|  'doctor',
57|  'Check whether the local oh-my-pi and bun runtime are available.',
58|  {},
59|  async () => {
60|    const checks = await runDoctor();
61|    return {
62|      content: [
63|        {
64|          type: 'text',
65|          text: JSON.stringify({ checks }, null, 2),
66|        },
67|      ],
68|    };
69|  }
70|);
