{"content": "1|import { spawn } from 'node:child_process';
2|import { accessSync, constants } from 'node:fs';
3|import { delimiter, join, resolve as resolvePath } from 'node:path';
4|
5|export function resolveCommand(envKey, fallback) {
6|  const value = process.env[envKey]?.trim();
7|  return value || fallback;
8|}
9|
10|export function findExecutable(command) {
11|  if (!command) return null;
12|  if (command.includes('/') || command.includes('\\')) {
13|    try {
14|      accessSync(command, constants.X_OK);
15|      return command;
16|    } catch {
17|      return null;
18|    }
19|  }
20|
21|  for (const part of (process.env.PATH || '').split(delimiter)) {
22|    if (!part) continue;
23|    const candidate = join(part, command);
24|    try {
25|      accessSync(candidate, constants.X_OK);
26|      return candidate;
27|    } catch {
28|      continue;
29|    }
30|  }
31|  return null;
32|}
33|
34|export function resolveOmpBinary() {
35|  const configured = resolveCommand('OMP_BIN', 'omp');
36|  return findExecutable(configured) || configured;
37|}
38|
39|export function resolveRunnerBinary() {
40|  return resolveCommand('BUN_BIN', 'bun');
41|}
42|
43|export function buildOmpArgs({ prompt, cwd, model, provider, profile, noSession = false, mode = 'json' }) {
44|  const args = [];
45|  if (mode) args.push('--mode', mode);
46|  if (noSession) args.push('--no-session');
47|  if (cwd) args.push('--cwd', cwd);
48|  if (model) args.push('--model', model);
49|  if (provider) args.push('--provider', provider);
50|  if (profile) args.push('--profile', profile);
51|  args.push(prompt);
52|  return args;
53|}
54|
55|export function normalizeCwd(cwd) {
56|  return cwd ? resolvePath(cwd) : undefined;
57|}
58|
59|export async function runCommand(command, args, options = {}) {
60|  return await new Promise((resolve, reject) => {
61|    const child = spawn(command, args, {
62|      cwd: options.cwd,
63|      env: { ...process.env, ...(options.env || {}) },
64|      shell: false,
65|      stdio: ['ignore', 'pipe', 'pipe'],
66|    });
67|
68|    let stdout = '';
69|    let stderr = '';
70|    child.stdout.on('data', (chunk) => (stdout += chunk));
71|    child.stderr.on('data', (chunk) => (stderr += chunk));
72|    child.on('error', reject);
73|    child.on('close', (code) => {
74|      resolve({ code: code ?? 1, stdout, stderr });
75|    });
76|  });
77|}
78|
79|export function safeParseJson(text) {
80|  try {
81|    return JSON.parse(text);
82|  } catch {
83|    return null;
84|  }
85|}
86|
87|export async function doctor() {
88|  const ompBin = resolveCommand('OMP_BIN', 'omp');
89|  const bunBin = resolveCommand('BUN_BIN', 'bun');
90|  const checks = [];
91|
92|  try {
93|    const omp = await runCommand(bunBin, [ompBin, '--version']);
94|    checks.push({ name: 'omp', command: ompBin, ok: omp.code === 0, output: (omp.stdout || omp.stderr).trim() });
95|  } catch (error) {
96|    checks.push({ name: 'omp', command: ompBin, ok: false, output: error instanceof Error ? error.message : String(error) });
97|  }
98|
99|  try {
100|    const bun = await runCommand(bunBin, ['--version']);
101|    checks.push({ name: 'bun', command: bunBin, ok: bun.code === 0, output: (bun.stdout || bun.stderr).trim() });
102|  } catch (error) {
103|    checks.push({ name: 'bun', command: bunBin, ok: false, output: error instanceof Error ? error.message : String(error) });
104|  }
105|
106|  return checks;
